/**
 * The four rule sets the emulator tests run against (Phase 11C.2):
 *   current   firebase/rules/android-baseline.rules  the repository rules of the Android app (a copy of android/firestore.rules)
 *   A         firebase/firestore.rules             Part A: wallet integrity (the production deployment candidate)
 *   B         firebase/rules/part-b.rules          Part B: habit, completion and note validation (not a candidate yet)
 *   AB        firebase/rules/combined.rules        A + B (the eventual end state)
 * A and B are generated by `scripts/build-rules.mjs` from shared pieces (`tests/rulesBuild.test.ts` checks they are up to date).
 */
import { readFileSync } from 'node:fs';
import { join } from 'node:path';
import { assertFails, assertSucceeds } from '@firebase/rules-unit-testing';

const root = join(__dirname, '..', '..');
const read = (p: string) => readFileSync(join(root, p), 'utf8');

export const RULESETS = {
  current: read('firebase/rules/android-baseline.rules'),
  A: read('firebase/firestore.rules'),
  B: read('firebase/rules/part-b.rules'),
  AB: read('firebase/rules/combined.rules'),
} as const;
export type RuleSet = keyof typeof RULESETS;
export const ALL_SETS = Object.keys(RULESETS) as RuleSet[];

/** Rule sets that include Part A (wallet integrity) / Part B (document validation). */
export const WITH_A: readonly RuleSet[] = ['A', 'AB'];
export const WITH_B: readonly RuleSet[] = ['B', 'AB'];
/** Rule sets that refuse a write the rules in force accept, whichever part does it (for example a nested path under a habit). */
export const WITH_ANY: readonly RuleSet[] = ['A', 'B', 'AB'];

/** `assertFails` for the rule sets listed, `assertSucceeds` for every other one. */
export const refusedBy = (rs: RuleSet, sets: readonly RuleSet[]) => (sets.includes(rs) ? assertFails : assertSucceeds);
